package com.ebdf.controller;
import com.ebdf.dao.PortalDAO; import com.google.gson.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*;
@WebServlet("/api/admin/*") public class AdminServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO(); private final Gson gson=new Gson();
 private boolean admin(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return false;}if(!"ADMIN".equals(s.getAttribute("userRole"))){p.setStatus(403);p.getWriter().write("{\"message\":\"Administrator access required\"}");return false;}return true;}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");if(!admin(q,p))return;try{String path=q.getPathInfo();Object data;if(path==null||"/stats".equals(path))data=dao.adminStats();else if("/users".equals(path))data=dao.adminUsers();else if("/donors".equals(path))data=dao.adminDonors();else if("/requests".equals(path))data=dao.adminRequests();else if("/donations".equals(path))data=dao.adminDonations();else if("/reports".equals(path))data=dao.adminReports();else{p.setStatus(404);p.getWriter().write("{\"message\":\"Unknown admin resource\"}");return;}p.getWriter().write(gson.toJson(data));}catch(Exception e){getServletContext().log("admin query failed",e);p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load admin data\"}");}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");if(!admin(q,p))return;try{JsonObject j=gson.fromJson(q.getReader(),JsonObject.class);String action=j.get("action").getAsString();int id=j.get("id").getAsInt();String status=j.get("status").getAsString().toUpperCase(java.util.Locale.ROOT);boolean ok=switch(action){case "userStatus"->java.util.Set.of("ACTIVE","INACTIVE","SUSPENDED").contains(status)&&dao.setUserStatus(id,status);case "donorAvailability"->java.util.Set.of("AVAILABLE","UNAVAILABLE").contains(status)&&dao.setDonorAvailability(id,status);case "requestStatus"->java.util.Set.of("OPEN","MATCHED","FULFILLED","CANCELLED","CLOSED").contains(status)&&dao.setRequestStatus(id,status);case "donationStatus"->java.util.Set.of("PENDING","VERIFIED","REJECTED").contains(status)&&dao.verifyDonation(id,status);default->false;};if(!ok){p.setStatus(400);p.getWriter().write("{\"message\":\"Action could not be completed\"}");return;}p.getWriter().write("{\"message\":\"Record updated successfully\"}");}catch(Exception e){getServletContext().log("admin update failed",e);p.setStatus(400);p.getWriter().write("{\"message\":\"Invalid admin action\"}");}}
}
